  var t = g.text(label).font({size:14,weight:'bold',family:'serif'}).fill(isMarked?'#fff':BLACK).attr({'text-anchor':'middle','dominant-baseline':'central'});
  t.move(x, y);
  if(id) { c.attr('data-node',id); t.attr('data-node',id); }
  return {circle:c, text:t};
}

// ── Panel (a): Tree view ──
var gA = draw.group();
// Panel label
gA.text('(a)').font({size:16,family:'serif',style:'italic'}).fill(BLACK).move(20,100);
// H.min label + arrow
gA.text('H.min').font({size:16,family:'serif',style:'italic'}).fill(BLACK).attr({'text-anchor':'middle'}).move(500,20);
drawArrow(gA, 500,42, 500,110-R-4, BLACK, 2);
// Dashed root list line
gA.line(posA['23'].x, posA['23'].y, posA['24'].x, posA['24'].y).stroke({color:BLACK,width:1.5,'stroke-dasharray':'6,4'});
// Tree edges
var edgesA = [['3','18'],['3','52'],['3','38'],['18','39'],['38','41'],['17','30'],['24','26'],['24','46'],['26','35']];
edgesA.forEach(function(e){
  var p=posA[e[0]], c=posA[e[1]];
  gA.line(p.x,p.y,c.x,c.y).stroke({color:BLACK,width:1.5});
});
// Nodes
Object.keys(posA).forEach(function(k){
  var p=posA[k];
  var nd = drawNode(gA, p.x, p.y, k, marked[k], 'a-'+k);
  nd.circle.on('mousemove',function(ev){showTooltip('Node '+k+(marked[k]?' (marked)':''),ev);}).on('mouseleave',hideTooltip);
});

// ── Panel (b): Pointer view ──
var gB = draw.group();
gB.text('(b)').font({size:16,family:'serif',style:'italic'}).fill(BLACK).move(20,470);
// H.min label + arrow (will be updated for insert)
var hminLabelB = gB.text('H.min').font({size:16,family:'serif',style:'italic'}).fill(BLACK).attr({'text-anchor':'middle'}).move(500,390);
var hminArrowB = drawArrow(gB, 500,412, 500,480-R-4, BLACK, 2);

// Circular doubly linked list arrows for root list
function drawCircularList(g, nodeList, positions, yOff) {
  yOff = yOff || 0;
  var n = nodeList.length;
  for(var i=0;i<n;i++){
    var cur = nodeList[i], nxt = nodeList[(i+1)%n];
    var p1 = positions[cur], p2 = positions[nxt];
    if(i < n-1) {
      // Forward arrow (above)
      var off = 6;
      drawArrow(g, p1.x+R+2, p1.y-off, p2.x-R-2, p2.y-off, BLACK, 1.2);
      // Backward arrow (below)
      drawArrow(g, p2.x-R-2, p2.y+off, p1.x+R+2, p1.y+off, BLACK, 1.2);
    } else {
      // Wrap-around: draw curved arrows above/below
      var startX = p1.x, endX = p2.x;
      var topY = p1.y - R - 14;
      // Forward (right to left, going above)
      var path1 = g.path('M '+startX+' '+(p1.y-R-2)+' C '+startX+' '+topY+', '+endX+' '+topY+', '+endX+' '+(p2.y-R-2))
        .fill('none').stroke({color:BLACK,width:1.2});
      // arrowhead at end
      drawArrow(g, endX, p2.y-R-6, endX, p2.y-R-2, BLACK, 1.2);
      // Backward (left to right, going below)
      var botY = p1.y + R + 14;
      var path2 = g.path('M '+endX+' '+(p2.y+R+2)+' C '+endX+' '+botY+', '+startX+' '+botY+', '+startX+' '+(p1.y+R+2))
        .fill('none').stroke({color:BLACK,width:1.2});
      drawArrow(g, startX, p1.y+R+6, startX, p1.y+R+2, BLACK, 1.2);
    }
  }
}

// Root list circular arrows
drawCircularList(gB, roots, posB);

// Child list circular arrows
Object.keys(children).forEach(function(p){
  var kids = children[p];
  if(kids.length > 1) {
    drawCircularList(gB, kids, posB);
  } else {
    // Single node: self-loop
    var kp = posB[kids[0]];
    var loopR = 14;
    gB.path('M '+(kp.x-R-2)+' '+kp.y+' C '+(kp.x-R-loopR)+' '+(kp.y-loopR)+', '+(kp.x-R-loopR)+' '+(kp.y+loopR)+', '+(kp.x-R-2)+' '+kp.y)
      .fill('none').stroke({color:BLACK,width:1.2});
    drawArrow(gB, kp.x-R-5, kp.y+3, kp.x-R-2, kp.y, BLACK, 1.2);
  }
});

// Parent/child vertical arrows
Object.keys(children).forEach(function(p){
  var pp = posB[p];
  children[p].forEach(function(c){
    var cp = posB[c];
    // Down arrow (parent to child)
    drawArrow(gB, pp.x-4, pp.y+R+2, cp.x-4, cp.y-R-2, BLACK, 1.2);
    // Up arrow (child to parent)
    drawArrow(gB, cp.x+4, cp.y-R-2, pp.x+4, pp.y+R+2, BLACK, 1.2);
  });
});

// Nodes for panel (b)
var nodeElsB = {};
Object.keys(posB).forEach(function(k){
  var p=posB[k];
  var nd = drawNode(gB, p.x, p.y, k, marked[k], 'b-'+k);
  nodeElsB[k] = nd;
  nd.circle.css('cursor','pointer');
  nd.circle.on('click', function(){ highlightNode(k); });
  nd.circle.on('mousemove',function(ev){showTooltip('Click to see pointers of node '+k,ev);}).on('mouseleave',hideTooltip);
});

// ── Highlight pointers on click ──
var highlightGroup = draw.group();
var selectedNode = null;

function highlightNode(k) {
  highlightGroup.clear();
  if(selectedNode === k) { selectedNode = null; return; }
  selectedNode = k;
  var p = posB[k];
  // Highlight sibling pointers (left/right in list)
  var list = null;
  if(roots.indexOf(k)>=0) list = roots;
  else {
    Object.keys(children).forEach(function(par){
      if(children[par].indexOf(k)>=0) list = children[par];
    });
  }
  if(list && list.length > 1) {
    var idx = list.indexOf(k);
    var left = list[(idx-1+list.length)%list.length];
    var right = list[(idx+1)%list.length];
    var lp = posB[left], rp = posB[right];
    // Highlight arrows to/from left and right siblings
    highlightGroup.line(p.x-R-2, p.y-6, lp.x+R+2, lp.y-6).stroke({color:ACCENT,width:3,linecap:'round'});
    highlightGroup.line(p.x-R-2, p.y+6, lp.x+R+2, lp.y+6).stroke({color:ACCENT,width:3,linecap:'round'});
    highlightGroup.line(p.x+R+2, p.y-6, rp.x-R-2, rp.y-6).stroke({color:ACCENT,width:3,linecap:'round'});
    highlightGroup.line(p.x+R+2, p.y+6, rp.x-R-2, rp.y+6).stroke({color:ACCENT,width:3,linecap:'round'});
  }
  // Parent pointer
  if(parentOf[k]) {
    var pp = posB[parentOf[k]];
    highlightGroup.line(p.x+4, p.y-R-2, pp.x+4, pp.y+R+2).stroke({color:ACCENT,width:3,linecap:'round'});
  }
  // Child pointer
  if(children[k]) {
    var cp = posB[children[k][0]];
    highlightGroup.line(p.x-4, p.y+R+2, cp.x-4, cp.y-R-2).stroke({color:ACCENT,width:3,linecap:'round'});
  }
  // Highlight the node itself
  highlightGroup.circle(R*2+6).center(p.x,p.y).fill('none').stroke({color:ACCENT,width:2.5,'stroke-dasharray':'4,3'});
}

// ── Insert animation ──
var insertState = 'idle'; // idle, spliced, minUpdated
var insertGroup = draw.group();
var newNodePos = {x:200, y:480}; // between 23 and 7

function renderInsert() {
  insertGroup.clear();
  if(insertState === 'idle') return;
  // Draw new node 2
  var nd = drawNode(insertGroup, newNodePos.x, newNodePos.y, '2', false, 'b-2');
  // Splice arrows (highlighted)
  if(insertState === 'spliced' || insertState === 'minUpdated') {
    // Connect to 23 (left) and 7 (right)
    var p23 = posB['23'], p7 = posB['7'];
    insertGroup.line(newNodePos.x-R-2, newNodePos.y-6, p23.x+R+2, p23.y-6).stroke({color:ACCENT,width:2.5,linecap:'round'});
    insertGroup.line(p23.x+R+2, p23.y+6, newNodePos.x-R-2, newNodePos.y+6).stroke({color:ACCENT,width:2.5,linecap:'round'});
    insertGroup.line(newNodePos.x+R+2, newNodePos.y-6, p7.x-R-2, p7.y-6).stroke({color:ACCENT,width:2.5,linecap:'round'});
    insertGroup.line(p7.x-R-2, p7.y+6, newNodePos.x+R+2, newNodePos.y+6).stroke({color:ACCENT,width:2.5,linecap:'round'});
    // Self-loop for child list (empty)
    insertGroup.path('M '+(newNodePos.x-R-2)+' '+newNodePos.y+' C '+(newNodePos.x-R-14)+' '+(newNodePos.y-14)+', '+(newNodePos.x-R-14)+' '+(newNodePos.y+14)+', '+(newNodePos.x-R-2)+' '+newNodePos.y)
      .fill('none').stroke({color:ACCENT,width:1.5});
  }
  if(insertState === 'minUpdated') {
    // Move H.min arrow to node 2
    hminArrowB.attr({opacity:0});
    hminLabelB.move(newNodePos.x, 390);
    drawArrow(insertGroup, newNodePos.x, 412, newNodePos.x, newNodePos.y-R-4, ACCENT, 2.5);
  } else {
    hminArrowB.attr({opacity:1});
    hminLabelB.move(500, 390);
  }
}

function trigger_insertStep() {
  if(insertState === 'idle') insertState = 'spliced';
  else if(insertState === 'spliced') insertState = 'minUpdated';
  else insertState = 'idle';
  renderInsert();
  updateInsertBtnLabel();
}
function updateInsertBtnLabel() {
  var btn = document.getElementById('insertStepBtn');
  if(insertState==='idle') btn.textContent='FIB-HEAP-INSERT key 2';
  else if(insertState==='spliced') btn.textContent='Step: update H.min';
  else btn.textContent='Reset insert';
}

// ── View mode toggle ──
var pointerView = false;
function toggle_viewMode(on) {
  pointerView = on;
  if(on) {
    gA.attr({opacity:0.3});
    gB.attr({opacity:1});
  } else {
    gA.attr({opacity:1});
    gB.attr({opacity:0.3});
  }
  highlightGroup.clear();
  selectedNode = null;
}

// ── Demo steps ──
var steps = [
  {
    title: "One heap, abstract view",
    narration: "Panel (a) shows five min-heap-ordered trees sharing a circular root list (the dashed ring through 23, 7, 3, 17, 24); H.min points to the smallest root, 3, and the black-filled nodes 18, 39, 26 are marked because each has lost a child since becoming a root.",
    state: { viewMode: false, insertStep: 'idle' }
  },
  {
    title: "Expose the pointers",
    narration: "Switch to the pointer view and click node 3: its four fields light up — a parent pointer (none, it is a root), a child pointer down to its list {18,52,38}, and left/right sibling pointers into the circular root list. Click other nodes to see the same four-field pattern holding every list together.",
    state: { viewMode: true, insertStep: 'idle' }
  },
  {
    title: "O(1) insert",
    narration: "Step the insert of key 2: the new node is spliced between two existing roots by rewiring just a few left/right pointers (spliced), then because 2 < 3 the H.min arrow jumps to it (minUpdated) — no tree is touched, which is why insertion is constant time.",
    state: { viewMode: true, insertStep: 'minUpdated' }
  }
];
var currentStep = 0;

function applyStep(idx) {
  currentStep = idx;
  var s = steps[idx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (idx+1)+'/'+steps.length+' '+s.title;
  // Apply state
  var cb = document.getElementById('viewModeInput');
  cb.checked = s.state.viewMode;
  toggle_viewMode(s.state.viewMode);
  insertState = s.state.insertStep;
  renderInsert();
  updateInsertBtnLabel();
}

function nextStep() { if(currentStep < steps.length-1) applyStep(currentStep+1); }
function prevStep() { if(currentStep > 0) applyStep(currentStep-1); }

// Initialize
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A Fibonacci heap is a collection of min-heap-ordered trees whose roots and whose children are each kept in circular doubly linked lists, and it is exactly this pointer structure that lets operations like insert run in O(1) by splicing a node with a constant number of pointer updates.
KEY INSIGHT (what students should walk away understanding): The circular doubly linked lists of roots and of children are the entire secret behind Fibonacci-heap efficiency: insert (and many other operations) only rewire a constant number of neighbor pointers and never rebuild a tree, giving O(1) amortized insertion.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A Fibonacci heap is a collection of min-heap-ordered trees whose roots and whose children are each kept in circular doubly linked lists, and it is exactly this pointer structure that lets operations like insert run in O(1) by splicing a node with a constant number of pointer updates.",
  "figureType": "network_diagram",
  "elements": [
    "panel label (a) and panel label (b)",
    "H.min label with a downward arrow pointing to root node 3 (present in both panels)",
    "root-list nodes 23, 7, 3, 17, 24 drawn as gray circles with black numerals",
    "panel (a) horizontal dashed line connecting the five roots to denote the circular root list abstractly",
    "tree edges in (a): 3-18, 3-52, 3-38, 18-39, 38-41, 17-30, 24-26, 24-46, 26-35",
    "child nodes 52, 38, 41, 30, 46, 35 as gray circles with black numerals",
    "marked nodes 18, 39, 26 drawn as filled black circles with white numerals",
    "panel (b) circular doubly linked root list: paired forward/backward directed arrows among 23, 7, 3, 17, 24",
    "panel (b) child sibling lists as circular doubly linked lists with paired arrows: {18,52,38}, {39}, {41}, {30}, {26,46}, {35}",
    "panel (b) vertical parent/child pointer arrows between each parent and its child list",
    "newly inserted node 2 (appears during the insert animation) spliced into the root list"
  ],
  "interactions": [
    {
      "id": "viewMode",
      "type": "toggle",
      "label": "Representation",
      "options": [
        "Tree view (a)",
        "Pointer view (b)"
      ],
      "default": "Tree view (a)",
      "teaches": "The same heap can be drawn as abstract trees with a dashed root ring or as an explicit pointer diagram; the tree view hides the linked-list machinery that the pointer view exposes, and both encode identical parent/child/sibling relationships plus the same marked nodes and H.min pointer."
    },
    {
      "id": "nodeSelect",
      "type": "click",
      "teaches": "Every node stores exactly four pointer fields — parent, child, left sibling, right sibling — and the left/right pairs are what make each sibling group and the root list a circular doubly linked list, so any node can be removed or spliced by rewiring only its immediate neighbors."
    },
    {
      "id": "insertStep",
      "type": "button",
      "label": "FIB-HEAP-INSERT key 2",
      "states": [
        "idle",
        "spliced",
        "minUpdated"
      ],
      "default": "idle",
      "teaches": "Inserting splices the new node into the circular root list with a constant number of pointer changes and then compares its key against H.min; because no tree is restructured, the whole operation is O(1), and H.min moves to the new node only when its key is smaller than the current minimum."
    }
  ],
  "demo_steps": [
    {
      "title": "One heap, abstract view",
      "narration": "Panel (a) shows five min-heap-ordered trees sharing a circular root list (the dashed ring through 23, 7, 3, 17, 24); H.min points to the smallest root, 3, and the black-filled nodes 18, 39, 26 are marked because each has lost a child since becoming a root.",
      "state": {
        "viewMode": "Tree view (a)",
        "insertStep": "idle"
      }
    },
    {
      "title": "Expose the pointers",
      "narration": "Switch to the pointer view and click node 3: its four fields light up — a parent pointer (none, it is a root), a child pointer down to its list {18,52,38}, and left/right sibling pointers into the circular root list. Click other nodes to see the same four-field pattern holding every list together.",
      "state": {
        "viewMode": "Pointer view (b)",
        "insertStep": "idle"
      }
    },
    {
      "title": "O(1) insert",
      "narration": "Step the insert of key 2: the new node is spliced between two existing roots by rewiring just a few left/right pointers (spliced), then because 2 < 3 the H.min arrow jumps to it (minUpdated) — no tree is touched, which is why insertion is constant time.",
      "state": {
        "viewMode": "Pointer view (b)",
        "insertStep": "minUpdated"
      }
    }
  ],
  "keyInsight": "The circular doubly linked lists of roots and of children are the entire secret behind Fibonacci-heap efficiency: insert (and many other operations) only rewire a constant number of neighbor pointers and never rebuild a tree, giving O(1) amortized insertion.",
  "reconstructionNotes": "Lay out two stacked panels labeled (a) top and (b) bottom. In (a) place the five roots 23, 7, 3, 17, 24 on one horizontal row joined by a single dashed line; hang the child subtrees below with plain solid tree edges (3 over 18/52/38, 18 over 39, 38 over 41, 17 over 30, 24 over 26/46, 26 over 35). In (b) keep identical node positions but replace the dashed root line with paired forward/backward arrowheads forming a circular list, draw each child group as its own small circular doubly linked list with paired arrows, and add vertical parent/child arrows. Color unmarked nodes light gray with black numerals and marked nodes 18, 39, 26 solid black with white numerals in both panels. Draw H.min as a label above node 3 with a bold downward arrow. During the insert animation, fade in a new gray node 2 spliced into the root ring and animate the H.min arrow sliding from 3 to 2 on the final step; highlight a clicked node's four pointer arrows in a distinct accent color."
}

