  '39':{x:390,y:720},'41':{x:570,y:720},'35':{x:820,y:720}
};
var marked = {'18':true,'39':true,'26':true};

var roots = ['23','7','3','17','24'];
var children = {
  '3':['18','52','38'], '18':['39'], '38':['41'], '17':['30'], '24':['26','46'], '26':['35']
};
var parentOf = {};
Object.keys(children).forEach(function(p){ children[p].forEach(function(c){ parentOf[c]=p; }); });

// ── Helper: draw arrow with arrowhead ──
function drawArrow(g, x1,y1,x2,y2, color, width, dashed) {
  var dx=x2-x1, dy=y2-y1, len=Math.sqrt(dx*dx+dy*dy);
  if(len<1) return null;
  var ux=dx/len, uy=dy/len;
  var hs = Math.min(7, width*3.5);
  var ex=x2-ux*hs, ey=y2-uy*hs;
  var line = g.line(x1,y1,ex,ey).stroke({color:color||BLACK, width:width||1.5, linecap:'round'});
  if(dashed) line.attr('stroke-dasharray','5,4');
  var p1x=ex+ux*hs, p1y=ey+uy*hs;
  var p2x=ex-uy*hs*0.45, p2y=ey+ux*hs*0.45;
  var p3x=ex+uy*hs*0.45, p3y=ey-ux*hs*0.45;
  g.polygon([[p1x,p1y],[p2x,p2y],[p3x,p3y]].map(function(p){return p[0]+','+p[1];}).join(' ')).fill(color||BLACK);
  return line;
}

function drawNode(g, x, y, label, isMarked, id) {
  var c = g.circle(R*2).center(x,y).fill(isMarked?BLACK:GRAY).stroke({color:BLACK,width:1.5});
  var t = g.text(label).font({size:13,weight:'bold',family:'serif'}).fill(isMarked?'#fff':BLACK)
    .attr({'text-anchor':'middle','dominant-baseline':'central'});
  t.move(x, y);
  if(id) { c.attr('data-node',id); t.attr('data-node',id); }
  return {circle:c, text:t};
}

// ── Pill (rounded rect) around a list ──
function drawPill(g, x1, y1, x2, y2, padX, padY) {
  padX = padX || 14;
  padY = padY || 10;
  var rx = x1 - padX, ry = y1 - padY;
  var rw = (x2 - x1) + 2*padX, rh = (y2 - y1) + 2*padY;
  var radius = rh / 2;
  return g.rect(rw, rh).move(rx, ry).rx(radius).fill('none').stroke({color:PILL_STROKE, width:PILL_WIDTH});
}

// ── Panel (a): Tree view ──
var gA = draw.group();
gA.text('(a)').font({size:16,family:'serif',style:'italic'}).fill(BLACK).move(20,100);
gA.text('H.min').font({size:16,family:'serif',style:'italic'}).fill(BLACK).attr({'text-anchor':'middle'}).move(480,20);
drawArrow(gA, 480,42, 480,110-R-4, BLACK, 2);
// Dashed root list line
gA.line(posA['23'].x, posA['23'].y, posA['24'].x, posA['24'].y).stroke({color:BLACK,width:1.5,'stroke-dasharray':'6,4'});
// Tree edges
var edgesA = [['3','18'],['3','52'],['3','38'],['18','39'],['38','41'],['17','30'],['24','26'],['24','46'],['26','35']];
edgesA.forEach(function(e){
  var p=posA[e[0]], c=posA[e[1]];
  gA.line(p.x,p.y,c.x,c.y).stroke({color:BLACK,width:1.5});
});
// Nodes
Object.keys(posA).forEach(function(k){
  var p=posA[k];
  var nd = drawNode(gA, p.x, p.y, k, marked[k], 'a-'+k);
  nd.circle.on('mousemove',function(ev){showTooltip('Node '+k+(marked[k]?' (marked)':''),ev);}).on('mouseleave',hideTooltip);
});

// ── Panel (b): Pointer view with pills ──
var gB = draw.group();
gB.text('(b)').font({size:16,family:'serif',style:'italic'}).fill(BLACK).move(20,490);
var hminLabelB = gB.text('H.min').font({size:16,family:'serif',style:'italic'}).fill(BLACK).attr({'text-anchor':'middle'}).move(480,400);
var hminArrowB = drawArrow(gB, 480,422, 480,500-R-4, BLACK, 2);

// Draw pill for root list
var rootPill = drawPill(gB, posB['23'].x, posB['23'].y, posB['24'].x, posB['24'].y, 30, 16);

// Draw pills for child lists
var childPills = {};
Object.keys(children).forEach(function(p){
  var kids = children[p];
  var xs = kids.map(function(k){return posB[k].x;});
  var ys = kids.map(function(k){return posB[k].y;});
  var minX = Math.min.apply(null,xs), maxX = Math.max.apply(null,xs);
  var minY = Math.min.apply(null,ys), maxY = Math.max.apply(null,ys);
  childPills[p] = drawPill(gB, minX, minY, maxX, maxY, 22, 12);
});

// ── Circular list arrows inside pills ──
function drawListArrows(g, nodeList, positions, pillPadX, pillPadY) {
  pillPadX = pillPadX || 30;
  pillPadY = pillPadY || 16;
  var n = nodeList.length;
  var arrowW = 1.8;
  var off = 7; // vertical offset for forward/backward arrows

  for(var i=0;i<n;i++){
    var cur = nodeList[i], nxt = nodeList[(i+1)%n];
    var p1 = positions[cur], p2 = positions[nxt];
    if(i < n-1) {
      // Forward arrow (top edge, left to right)
      drawArrow(g, p1.x+R+3, p1.y-off, p2.x-R-3, p2.y-off, BLACK, arrowW);
      // Backward arrow (bottom edge, right to left)
      drawArrow(g, p2.x-R-3, p2.y+off, p1.x+R+3, p1.y+off, BLACK, arrowW);
    } else {
      // Wrap-around: right end to left end (top) and left end to right end (bottom)
      var rightX = p1.x, leftX = p2.x;
      var topY = p1.y - pillPadY - 4;
      var botY = p1.y + pillPadY + 4;
      // Forward wrap (right→left along top)
      var wrapPath1 = g.path('M '+(rightX+R+3)+' '+(p1.y-off)+' C '+(rightX+R+pillPadX)+' '+(p1.y-off)+', '+(rightX+R+pillPadX)+' '+topY+', '+((rightX+leftX)/2)+' '+topY+' C '+(leftX-R-pillPadX)+' '+topY+', '+(leftX-R-pillPadX)+' '+(p2.y-off)+', '+(leftX-R-3)+' '+(p2.y-off))
        .fill('none').stroke({color:BLACK,width:arrowW,linecap:'round'});
      // arrowhead at end
      drawArrow(g, leftX-R-8, p2.y-off, leftX-R-3, p2.y-off, BLACK, arrowW);
      // Backward wrap (left→right along bottom)
      var wrapPath2 = g.path('M '+(leftX-R-3)+' '+(p2.y+off)+' C '+(leftX-R-pillPadX)+' '+(p2.y+off)+', '+(leftX-R-pillPadX)+' '+botY+', '+((rightX+leftX)/2)+' '+botY+' C '+(rightX+R+pillPadX)+' '+botY+', '+(rightX+R+pillPadX)+' '+(p1.y+off)+', '+(rightX+R+3)+' '+(p1.y+off))
        .fill('none').stroke({color:BLACK,width:arrowW,linecap:'round'});
      drawArrow(g, rightX+R+8, p1.y+off, rightX+R+3, p1.y+off, BLACK, arrowW);
    }
  }
}

// Root list arrows
drawListArrows(gB, roots, posB, 30, 16);

// Child list arrows
Object.keys(children).forEach(function(p){
  var kids = children[p];
  if(kids.length > 1) {
    drawListArrows(gB, kids, posB, 22, 12);
  } else {
    // Single node: self-loop pill
    var kp = posB[kids[0]];
    var loopOff = 10;
    // Small self-loop arrow on left side
    gB.path('M '+(kp.x-R-3)+' '+(kp.y-4)+' C '+(kp.x-R-loopOff-6)+' '+(kp.y-loopOff)+', '+(kp.x-R-loopOff-6)+' '+(kp.y+loopOff)+', '+(kp.x-R-3)+' '+(kp.y+4))
      .fill('none').stroke({color:BLACK,width:1.8,linecap:'round'});
    drawArrow(gB, kp.x-R-7, kp.y+5, kp.x-R-3, kp.y+4, BLACK, 1.8);
    // Small self-loop arrow on right side
    gB.path('M '+(kp.x+R+3)+' '+(kp.y+4)+' C '+(kp.x+R+loopOff+6)+' '+(kp.y+loopOff)+', '+(kp.x+R+loopOff+6)+' '+(kp.y-loopOff)+', '+(kp.x+R+3)+' '+(kp.y-4))
      .fill('none').stroke({color:BLACK,width:1.8,linecap:'round'});
    drawArrow(gB, kp.x+R+7, kp.y-5, kp.x+R+3, kp.y-4, BLACK, 1.8);
  }
});

// Parent/child vertical double arrows
Object.keys(children).forEach(function(p){
  var pp = posB[p];
  var kids = children[p];
  // Find the pill boundaries
  var parentPillBottom = pp.y + 16; // root pill padY
  var childPillTop;
  if(childPills[p]) {
    var ys = kids.map(function(k){return posB[k].y;});
    childPillTop = Math.min.apply(null,ys) - 12;
  } else {
    childPillTop = kids[0] ? posB[kids[0]].y - 12 : pp.y + 60;
  }
  // For root→child: parent is in root pill, child is in child pill
  var isRoot = roots.indexOf(p) >= 0;
  var pBot = isRoot ? pp.y + 16 : pp.y + 12;
  var cTop = childPillTop;

  kids.forEach(function(c){
    var cp = posB[c];
    // Down arrow (parent→child)
    drawArrow(gB, pp.x-4, pBot+2, cp.x-4, cTop-2, BLACK, 1.8);
    // Up arrow (child→parent)
    drawArrow(gB, cp.x+4, cTop-2, pp.x+4, pBot+2, BLACK, 1.8);
  });
});

// Nodes for panel (b)
var nodeElsB = {};
Object.keys(posB).forEach(function(k){
  var p=posB[k];
  var nd = drawNode(gB, p.x, p.y, k, marked[k], 'b-'+k);
  nodeElsB[k] = nd;
  nd.circle.css('cursor','pointer');
  nd.circle.on('click', function(){ highlightNode(k); });
  nd.circle.on('mousemove',function(ev){showTooltip('Click to see pointers of node '+k,ev);}).on('mouseleave',hideTooltip);
});

// ── Highlight pointers on click ──
var highlightGroup = draw.group();
var selectedNode = null;

function highlightNode(k) {
  highlightGroup.clear();
  if(selectedNode === k) { selectedNode = null; return; }
  selectedNode = k;
  var p = posB[k];
  var off = 7;
  // Highlight sibling pointers
  var list = null;
  if(roots.indexOf(k)>=0) list = roots;
  else {
    Object.keys(children).forEach(function(par){
      if(children[par].indexOf(k)>=0) list = children[par];
    });
  }
  if(list && list.length > 1) {
    var idx = list.indexOf(k);
    var left = list[(idx-1+list.length)%list.length];
    var right = list[(idx+1)%list.length];
    var lp = posB[left], rp = posB[right];
    highlightGroup.line(p.x-R-2, p.y-off, lp.x+R+2, lp.y-off).stroke({color:ACCENT,width:3,linecap:'round'});
    highlightGroup.line(p.x-R-2, p.y+off, lp.x+R+2, lp.y+off).stroke({color:ACCENT,width:3,linecap:'round'});
    highlightGroup.line(p.x+R+2, p.y-off, rp.x-R-2, rp.y-off).stroke({color:ACCENT,width:3,linecap:'round'});
    highlightGroup.line(p.x+R+2, p.y+off, rp.x-R-2, rp.y+off).stroke({color:ACCENT,width:3,linecap:'round'});
  }
  // Parent pointer
  if(parentOf[k]) {
    var pp = posB[parentOf[k]];
    highlightGroup.line(p.x+4, p.y-R-2, pp.x+4, pp.y+R+2).stroke({color:ACCENT,width:3,linecap:'round'});
  }
  // Child pointer
  if(children[k]) {
    var cp = posB[children[k][0]];
    highlightGroup.line(p.x-4, p.y+R+2, cp.x-4, cp.y-R-2).stroke({color:ACCENT,width:3,linecap:'round'});
  }
  // Highlight ring
  highlightGroup.circle(R*2+8).center(p.x,p.y).fill('none').stroke({color:ACCENT,width:2.5,'stroke-dasharray':'4,3'});
}

// ── Insert animation ──
var insertState = 'idle';
var insertGroup = draw.group();
var newNodePos = {x:185, y:500};

function renderInsert() {
  insertGroup.clear();
  if(insertState === 'idle') {
    hminArrowB.attr({opacity:1});
    hminLabelB.move(480, 400);
    return;
  }
  var nd = drawNode(insertGroup, newNodePos.x, newNodePos.y, '2', false, 'b-2');
  var off = 7;
  if(insertState === 'spliced' || insertState === 'minUpdated') {
    var p23 = posB['23'], p7 = posB['7'];
    // Splice arrows
    insertGroup.line(newNodePos.x-R-2, newNodePos.y-off, p23.x+R+2, p23.y-off).stroke({color:ACCENT,width:2.5,linecap:'round'});
    insertGroup.line(p23.x+R+2, p23.y+off, newNodePos.x-R-2, newNodePos.y+off).stroke({color:ACCENT,width:2.5,linecap:'round'});
    insertGroup.line(newNodePos.x+R+2, newNodePos.y-off, p7.x-R-2, p7.y-off).stroke({color:ACCENT,width:2.5,linecap:'round'});
    insertGroup.line(p7.x-R-2, p7.y+off, newNodePos.x+R+2, newNodePos.y+off).stroke({color:ACCENT,width:2.5,linecap:'round'});
    // Self-loop
    insertGroup.path('M '+(newNodePos.x-R-3)+' '+(newNodePos.y-4)+' C '+(newNodePos.x-R-16)+' '+(newNodePos.y-10)+', '+(newNodePos.x-R-16)+' '+(newNodePos.y+10)+', '+(newNodePos.x-R-3)+' '+(newNodePos.y+4))
      .fill('none').stroke({color:ACCENT,width:1.5});
  }
  if(insertState === 'minUpdated') {
    hminArrowB.attr({opacity:0});
    hminLabelB.move(newNodePos.x, 400);
    drawArrow(insertGroup, newNodePos.x, 422, newNodePos.x, newNodePos.y-R-4, ACCENT, 2.5);
  } else {
    hminArrowB.attr({opacity:1});
    hminLabelB.move(480, 400);
  }
}

function trigger_insertStep() {
  if(insertState === 'idle') insertState = 'spliced';
  else if(insertState === 'spliced') insertState = 'minUpdated';
  else insertState = 'idle';
  renderInsert();
  updateInsertBtnLabel();
}
function updateInsertBtnLabel() {
  var btn = document.getElementById('insertStepBtn');
  if(insertState==='idle') btn.textContent='FIB-HEAP-INSERT key 2';
  else if(insertState==='spliced') btn.textContent='Step: update H.min';
  else btn.textContent='Reset insert';
}

// ── View mode toggle ──
var pointerView = false;
function toggle_viewMode(on) {
  pointerView = on;
  if(on) {
    gA.attr({opacity:0.25});
    gB.attr({opacity:1});
  } else {
    gA.attr({opacity:1});
    gB.attr({opacity:0.25});
  }
  highlightGroup.clear();
  selectedNode = null;
}

// ── Demo steps ──
var steps = [
  {
    title: "One heap, abstract view",
    narration: "Panel (a) shows five min-heap-ordered trees sharing a circular root list (the dashed ring through 23, 7, 3, 17, 24); H.min points to the smallest root, 3, and the black-filled nodes 18, 39, 26 are marked because each has lost a child since becoming a root.",
    state: { viewMode: false, insertStep: 'idle' }
  },
  {
    title: "Expose the pointers",
    narration: "Switch to the pointer view and click node 3: its four fields light up — a parent pointer (none, it is a root), a child pointer down to its list {18,52,38}, and left/right sibling pointers into the circular root list. Click other nodes to see the same four-field pattern holding every list together.",
    state: { viewMode: true, insertStep: 'idle' }
  },
  {
    title: "O(1) insert",
    narration: "Step the insert of key 2: the new node is spliced between two existing roots by rewiring just a few left/right pointers (spliced), then because 2 < 3 the H.min arrow jumps to it (minUpdated) — no tree is touched, which is why insertion is constant time.",
    state: { viewMode: true, insertStep: 'minUpdated' }
  }
];
var currentStep = 0;

function applyStep(idx) {
  currentStep = idx;
  var s = steps[idx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (idx+1)+'/'+steps.length+' '+s.title;
  var cb = document.getElementById('viewModeInput');
  cb.checked = s.state.viewMode;
  toggle_viewMode(s.state.viewMode);
  insertState = s.state.insertStep;
  renderInsert();
  updateInsertBtnLabel();
}

function nextStep() { if(currentStep < steps.length-1) applyStep(currentStep+1); }
function prevStep() { if(currentStep > 0) applyStep(currentStep-1); }

// Initialize: both panels visible, panel (a) emphasized
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
