gA.text('(a)').font({size:20,family:'Georgia, serif',style:'italic'}).fill(BLACK).move(18,108);
gA.text('H.min').font({size:20,family:'Georgia, serif',style:'italic'}).fill(BLACK).attr({'text-anchor':'middle'}).move(480,18);
drawArrow(gA, 480,44, 480,120-R-4, BLACK, 2.2);
