});

// ── Panel (b): Pointer view ──
var gB = draw.group();
gB.text('(b)').font({size:20,family:'Georgia, serif',style:'italic'}).fill(BLACK).move(18,533);
var hminLabelB = gB.text('H.min').font({size:20,family:'Georgia, serif',style:'italic'}).fill(BLACK).attr({'text-anchor':'middle'}).move(480,432);
var hminArrowB = drawArrow(gB, 480,458, 480,545-R-4, BLACK, 2.2);

drawPill(gB, posB['23'].x, posB['23'].y, posB['24'].x, posB['24'].y, 32, rootPillPadY);
var childPills = {};
Object.keys(children).forEach(function(p){
  var kids = children[p];
  var xs = kids.map(function(k){return posB[k].x;});
  var ys = kids.map(function(k){return posB[k].y;});
  childPills[p] = drawPill(gB, Math.min.apply(null,xs), Math.min.apply(null,ys), Math.max.apply(null,xs), Math.max.apply(null,ys), 24, childPillPadY);
});

function drawListArrows(g, nodeList, positions, padX, padY) {
  var n = nodeList.length, arrowW = 1.7, off = 8;
  for(var i=0;i<n;i++){
    var cur = nodeList[i], nxt = nodeList[(i+1)%n];
    var p1 = positions[cur], p2 = positions[nxt];
    if(i < n-1) {
      drawArrow(g, p1.x+R+3, p1.y-off, p2.x-R-3, p2.y-off, BLACK, arrowW);
      drawArrow(g, p2.x-R-3, p2.y+off, p1.x+R+3, p1.y+off, BLACK, arrowW);
    } else {
      var rightX = p1.x, leftX = p2.x;
      var topY = p1.y - padY - 5, botY = p1.y + padY + 5;
      g.path('M '+(rightX+R+3)+' '+(p1.y-off)+' C '+(rightX+R+padX)+' '+(p1.y-off)+', '+(rightX+R+padX)+' '+topY+', '+((rightX+leftX)/2)+' '+topY+' C '+(leftX-R-padX)+' '+topY+', '+(leftX-R-padX)+' '+(p2.y-off)+', '+(leftX-R-3)+' '+(p2.y-off))
        .fill('none').stroke({color:BLACK,width:arrowW,linecap:'round'});
      drawArrow(g, leftX-R-9, p2.y-off, leftX-R-3, p2.y-off, BLACK, arrowW);
      g.path('M '+(leftX-R-3)+' '+(p2.y+off)+' C '+(leftX-R-padX)+' '+(p2.y+off)+', '+(leftX-R-padX)+' '+botY+', '+((rightX+leftX)/2)+' '+botY+' C '+(rightX+R+padX)+' '+botY+', '+(rightX+R+padX)+' '+(p1.y+off)+', '+(rightX+R+3)+' '+(p1.y+off))
        .fill('none').stroke({color:BLACK,width:arrowW,linecap:'round'});
      drawArrow(g, rightX+R+9, p1.y+off, rightX+R+3, p1.y+off, BLACK, arrowW);
    }
  }
}
drawListArrows(gB, roots, posB, 32, rootPillPadY);
Object.keys(children).forEach(function(p){
  var kids = children[p];
  if(kids.length > 1) {
    drawListArrows(gB, kids, posB, 24, childPillPadY);
  } else {
    var kp = posB[kids[0]], lo = 11;
    gB.path('M '+(kp.x-R-3)+' '+(kp.y-4)+' C '+(kp.x-R-lo-6)+' '+(kp.y-lo)+', '+(kp.x-R-lo-6)+' '+(kp.y+lo)+', '+(kp.x-R-3)+' '+(kp.y+4)).fill('none').stroke({color:BLACK,width:1.7,linecap:'round'});
    drawArrow(gB, kp.x-R-8, kp.y+5, kp.x-R-3, kp.y+4, BLACK, 1.7);
    gB.path('M '+(kp.x+R+3)+' '+(kp.y+4)+' C '+(kp.x+R+lo+6)+' '+(kp.y+lo)+', '+(kp.x+R+lo+6)+' '+(kp.y-lo)+', '+(kp.x+R+3)+' '+(kp.y-4)).fill('none').stroke({color:BLACK,width:1.7,linecap:'round'});
    drawArrow(gB, kp.x+R+8, kp.y-5, kp.x+R+3, kp.y-4, BLACK, 1.7);
  }
});

// Parent/child vertical double arrows
function pillBottomY(key){ return roots.indexOf(key)>=0 ? posB[key].y+rootPillPadY : posB[key].y+childPillPadY; }
function childPillTopY(p){ var ys=children[p].map(function(k){return posB[k].y;}); return Math.min.apply(null,ys)-childPillPadY; }
Object.keys(children).forEach(function(p){
  var pBot = pillBottomY(p), cTop = childPillTopY(p), px = posB[p].x;
  drawArrow(gB, px-5, pBot+2, px-5, cTop-2, BLACK, 1.7);
  drawArrow(gB, px+5, cTop-2, px+5, pBot+2, BLACK, 1.7);
});

var nodeElsB = {};
Object.keys(posB).forEach(function(k){
  var p=posB[k];
  var nd = drawNode(gB, p.x, p.y, k, marked[k]);
  nodeElsB[k] = nd;
  nd.circle.css('cursor','pointer');
  nd.circle.on('click', function(){ highlightNode(k); });
  nd.circle.on('mousemove',function(ev){showTooltip('Click node '+k+' to highlight its 4 pointer fields',ev);}).on('mouseleave',hideTooltip);
});

// ── Highlight 4 pointer fields on click ──
var highlightGroup = draw.group();
var selectedNode = null;
function highlightNode(k) {
  highlightGroup.clear();
  if(selectedNode === k) { selectedNode = null; return; }
  selectedNode = k;
  var p = posB[k], off = 8;
  var list = null;
  if(roots.indexOf(k)>=0) list = roots;
  else Object.keys(children).forEach(function(par){ if(children[par].indexOf(k)>=0) list = children[par]; });
  if(list && list.length > 1) {
    var idx = list.indexOf(k);
    var lp = posB[list[(idx-1+list.length)%list.length]], rp = posB[list[(idx+1)%list.length]];
    highlightGroup.line(p.x-R-2, p.y-off, lp.x+R+2, lp.y-off).stroke({color:ACCENT,width:3,linecap:'round'});
    highlightGroup.line(p.x-R-2, p.y+off, lp.x+R+2, lp.y+off).stroke({color:ACCENT,width:3,linecap:'round'});
    highlightGroup.line(p.x+R+2, p.y-off, rp.x-R-2, rp.y-off).stroke({color:ACCENT,width:3,linecap:'round'});
    highlightGroup.line(p.x+R+2, p.y+off, rp.x-R-2, rp.y+off).stroke({color:ACCENT,width:3,linecap:'round'});
  }
  if(parentOf[k]) {
    var pp = posB[parentOf[k]];
    highlightGroup.line(p.x+5, p.y-R-2, pp.x+5, pp.y+R+2).stroke({color:ACCENT,width:3,linecap:'round'});
  }
  if(children[k]) {
    var cp = posB[children[k][0]];
    highlightGroup.line(p.x-5, p.y+R+2, cp.x-5, cp.y-R-2).stroke({color:ACCENT,width:3,linecap:'round'});
  }
  highlightGroup.circle(R*2+9).center(p.x,p.y).fill('none').stroke({color:ACCENT,width:2.5,'stroke-dasharray':'4,3'});
}

// ── Insert animation ──
var insertState = 'idle';
var insertGroup = draw.group();
var newNodePos = {x:185, y:545};
function renderInsert() {
  insertGroup.clear();
  if(insertState === 'idle') { hminArrowB.attr({opacity:1}); hminLabelB.move(480,432); return; }
  drawNode(insertGroup, newNodePos.x, newNodePos.y, '2', false);
  var off = 8;
  if(insertState === 'spliced' || insertState === 'minUpdated') {
    var p23 = posB['23'], p7 = posB['7'];
    insertGroup.line(newNodePos.x-R-2, newNodePos.y-off, p23.x+R+2, p23.y-off).stroke({color:ACCENT,width:2.5,linecap:'round'});
    insertGroup.line(p23.x+R+2, p23.y+off, newNodePos.x-R-2, newNodePos.y+off).stroke({color:ACCENT,width:2.5,linecap:'round'});
    insertGroup.line(newNodePos.x+R+2, newNodePos.y-off, p7.x-R-2, p7.y-off).stroke({color:ACCENT,width:2.5,linecap:'round'});
    insertGroup.line(p7.x-R-2, p7.y+off, newNodePos.x+R+2, newNodePos.y+off).stroke({color:ACCENT,width:2.5,linecap:'round'});
  }
  if(insertState === 'minUpdated') {
    hminArrowB.attr({opacity:0});
    hminLabelB.move(newNodePos.x, 432);
    drawArrow(insertGroup, newNodePos.x, 458, newNodePos.x, newNodePos.y-R-4, ACCENT, 2.5);
  } else {
    hminArrowB.attr({opacity:1});
    hminLabelB.move(480,432);
  }
}
function trigger_insertStep() {
  if(insertState === 'idle') insertState = 'spliced';
  else if(insertState === 'spliced') insertState = 'minUpdated';
  else insertState = 'idle';
  renderInsert(); updateInsertBtnLabel();
}
function updateInsertBtnLabel() {
  var btn = document.getElementById('insertStepBtn');
  if(insertState==='idle') btn.textContent='FIB-HEAP-INSERT key 2';
  else if(insertState==='spliced') btn.textContent='Step: update H.min';
  else btn.textContent='Reset insert';
}

// ── View emphasis toggle (default: BOTH panels full opacity, faithful) ──
function toggle_viewMode(on) {
  if(on) { gA.attr({opacity:0.22}); gB.attr({opacity:1}); }
  else   { gA.attr({opacity:1});    gB.attr({opacity:1}); }
  highlightGroup.clear(); selectedNode = null;
}

