var steps = [
  { title:"One heap, abstract view",
    narration:"Both panels show the SAME heap. Panel (a) draws five min-heap-ordered trees on a dashed circular root ring (23, 7, 3, 17, 24); H.min points to the smallest root, 3. Black-filled nodes 18, 39, 26 are marked (each lost a child). Panel (b) below exposes the identical structure as explicit pointers.",
    state:{ viewMode:false, insertStep:'idle' } },
  { title:"Expose the pointers",
    narration:"Emphasize the pointer view and click node 3: its four fields light up — left/right sibling pointers into the circular root list, a child pointer down to the list {18,52,38}, and a parent pointer (none, it is a root). Click other nodes to see the same four-field pattern holding every circular list together.",
    state:{ viewMode:true, insertStep:'idle' } },
  { title:"O(1) insert",
    narration:"Step the insert of key 2: the new node is spliced between two roots by rewiring only a constant number of left/right pointers, then because 2 < 3 the H.min arrow jumps to it. No tree is rebuilt — that is exactly why insertion is O(1).",
    state:{ viewMode:true, insertStep:'minUpdated' } }
];
var currentStep = 0;
function applyStep(idx) {
  currentStep = idx;
  var s = steps[idx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (idx+1)+'/'+steps.length+' '+s.title;
  var cb = document.getElementById('viewModeInput');
  cb.checked = s.state.viewMode;
  toggle_viewMode(s.state.viewMode);
  insertState = s.state.insertStep;
  renderInsert(); updateInsertBtnLabel();
}
function nextStep(){ if(currentStep < steps.length-1) applyStep(currentStep+1); }
function prevStep(){ if(currentStep > 0) applyStep(currentStep-1); }

applyStep(0);
